let data,accountData={accounts:[],slots:[],candidates:[],revision:0},currentPeriod='2026-08',reloadSequence=0,switching=false,accountSearch='',csrf=null,view='overview',search='',country='',manager='',selectedSite='',currency='USD',pageIndex=0,day='',submitHandler=null,busy=false;
async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},body:JSON.stringify(body)});if(r.status===401){location.replace('/login');throw Error('Sessão encerrada');}const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível concluir.');if(d.pending){message(d.message);if($('#editor').open)$('#editor').close();throw Object.assign(Error(d.message),{pending:true});}return d;}
