async function reload(period=currentPeriod){const seq=++reloadSequence;const [next,accounts,periods]=await Promise.all([api('/api/workspace?period='+period),api('/api/ad-accounts?period='+period),api('/api/periods')]);if(seq!==reloadSequence)return;const changed=currentPeriod!==period;data=next;accountData=accounts;currentPeriod=period;if(changed){selectedSite='';search='';country='';manager='';day='';}$('#period').innerHTML=periods.map(p=>`<option value="${esc(p.id)}" ${p.id===period?'selected':''}>${esc(p.label)}</option>`).join('');$('#sync').textContent='Dados carregados';render();}
async function writable(){if(data.id==='baseline'){await api('/api/workspace/open',{period:currentPeriod});await reload();}return data.id;}
async function save(path,body){if($('#editor').open&&$('#editor').dataset.period!==currentPeriod)throw Error('O mês mudou; reabra o formulário.');const id=await writable();const before=data.revision;await api(`/api/scenarios/${id}/${path}`,{...body,period:currentPeriod,revision:before});await reload();if(data.revision<=before)throw Error('Gravação sem confirmação. Recarregue antes de repetir.');message('Alteração salva. Resultados recalculados e conferidos. A planilha foi preservada.');}
function num(v,profit=false){return `<span class="number ${n(v)<0?'negative':profit&&n(v)>0?'positive':''}">${esc(fmt(n(v)*(currency==='BRL'?n(data.fx):1),currency))}</span>`;}
function table(headers,rows,classes=[]){return `<div class="scroll"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${classes[i]||''}">${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panelhead"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>${body}</section>`;}
function cards(items){return '<div class="cards">'+items.map(([label,usd,brl,note,emphasis])=>`<div class="card ${emphasis?'emphasis':''}"><small>${esc(label)}</small><strong>${usd===null||usd===''?'—':esc(fmt(usd))}</strong><p>${brl===null||brl===''?'—':esc(fmt(brl,'BRL'))}${note?`<br>${esc(note)}`:''}</p></div>`).join('')+'</div>';}
function siteGroups(facts=data.domain.facts){const groups=new Map();for(const f of facts){let g=groups.get(f.site);if(!g){g={site:f.site,status:(data.sites||[]).find(s=>s.name===f.site)?.status||f.status,countries:new Set(),partners:new Set(),managers:new Set(),gross:0,net:0,tax:0,spend:0,profit:0,invalid:0};groups.set(f.site,g);}for(const k of ['gross','net','tax','spend','profit','invalid'])g[k]+=n(f[k]);g.countries.add(f.country);g.partners.add(f.partner);if(f.manager)for(const label of managerTokens(f.manager))g.managers.add(label);}return [...groups.values()].sort(siteOrder);}
function reviewStatus(e){return normalize(e.status||'').trim()==='conferido'?'Conferido':normalize(e.status||'').trim()==='a conferir'?'A conferir':e.status||'A conferir';}
function reviewDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.split('-').reverse().join('/'):'—';}
function reviewBadge(e){const status=reviewStatus(e);return `<span class="pill ${status==='Conferido'?'good':'warn'}">${esc(status)}</span>`;}
function summaryExpenses(category){const rows=data.domain.expenses.filter(e=>e.category===category&&e.label&&!e.archived).sort(expenseOrder);const usd=rows.reduce((s,e)=>s+n(e.usd),0),brl=rows.reduce((s,e)=>s+n(e.brl),0);const body=table([category==='company'?'Despesa Tipo':'Gestor / funcionário','Valor $','Valor R$','Status','Data da conferência'],rows.map(e=>[esc(expenseDisplayName(e.label)),esc(fmt(Math.abs(n(e.usd)))),esc(fmt(Math.abs(n(e.brl)),'BRL')),reviewBadge(e),esc(reviewDate(e.checked_on))]).concat([['TOTAL',esc(fmt(Math.abs(usd))),esc(fmt(Math.abs(brl),'BRL')),'','']]),rows.map(()=> '').concat(['subtotal']));return `<div data-summary-expenses="${category}">${panel(category==='company'?'Despesas Gerais':'Despesas dos funcionários',monthLabel()+' · somente visualização · edite pelo menu de despesas',body+'<div class="block-scroll-note">Role dentro da tabela para ver todos os lançamentos. Em telas menores, deslize para os lados para consultar valores, status e data da conferência.</div>')}</div>`;}
