 const labels={'F1 → Caixa J2':'USD → BRL','H1':'USD/CAD · Rede1','I1':'GBP → USD · YMonetize','J1':'Inválidos · ActiveView','K1':'Inválidos · YMonetize','L1':'Inválidos SB Rede1','EN82':'Inválidos · M2','network:SB Rede2':'Inválidos SB Rede2'};
