$('#logout').onclick=$('#logoutMobile').onclick=async()=>{await api('/api/auth/logout',{});location.replace('/login');};
$('#history').onclick=async()=>{try{const rows=await api('/api/scenarios/'+data.id+'/audit');openEditor('Histórico de alterações',rows.map(r=>`<div class="histrow"><strong>${esc(({AUTO_QUOTES_UPDATED:'Cotação automática atualizada',DAILY_INPUTS_CHANGED:'Receitas ou gastos alterados',EXPENSE_ADDED:'Despesa adicionada',EXPENSE_UPDATED:'Despesa atualizada',EXPENSE_ARCHIVED:'Despesa excluída do mês',FINANCIAL_RATE_CHANGED:'Câmbio ou inválidos alterados',WORKSPACE_CREATED:'Mês de trabalho iniciado',IMPORT_VERIFIED:'Dados de referência carregados'})[r.action]||r.action)}</strong><small>${esc(new Date(r.created_at).toLocaleString('pt-BR'))} · ${esc(r.actor)}</small></div>`).join('')||'<p>Nenhuma alteração neste mês.</p>',async()=>{},'Fechar');}catch(e){message(e.message,true);}};
api('/api/auth/me').then(async u=>{csrf=u.csrf;const requested=new URLSearchParams(location.search).get('view');if(['overview','movement','company','personnel','rates','sites','accounts'].includes(requested))view=requested;window.MGSNavigation.mount(u.role||'owner',view,false,u);if(u.role==='manager'){location.replace('/operations?view=manager');return;}if(u.role==='partner'){$('#history').hidden=true;document.querySelectorAll('.owner-only').forEach(e=>e.hidden=true);}await reload();if(!u.role||u.role==='owner'){const notices=async()=>{try{const a=await api('/api/finance/approvals'),n=a.filter(x=>x.status==='pending').length;$('#approvalCount').textContent=n?'('+n+')':'';if(n)message('Há '+n+' proposta(s) aguardando sua autorização em Aprovações.');}catch{}};await notices();setInterval(notices,30000);}}).catch(e=>message(e.message,true));
setInterval(()=>{if(!busy&&!$('#editor').open)reload().catch(e=>message('Não foi possível atualizar. Os últimos dados permanecem visíveis.',true));},300000);
